package cn.jingyu.deepseek.test;
import cn.jingyu.deepseek.*;import cn.jingyu.deepseek.NativeActivity;import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import org.json.*;import java.io.*;import java.lang.reflect.*;import java.util.concurrent.atomic.*;import java.util.zip.*;
/** Explicitly opted-in, real DeepSeek integration. Test key is external and deleted immediately. */
public final class RealAgentSmokeTest extends Instrumentation {
 private NativeActivity activity;private final StringBuilder report=new StringBuilder();public void onCreate(Bundle args){super.onCreate(args);start();}private void main(Runnable r){runOnMainSync(r);waitForIdleSync();}private Object field(String n)throws Exception{Field f=NativeActivity.class.getDeclaredField(n);f.setAccessible(true);return f.get(activity);}private JSONObject last()throws Exception{JSONObject state=(JSONObject)field("state");JSONArray messages=state.getJSONArray("chats").getJSONObject(0).getJSONArray("messages");return messages.getJSONObject(messages.length()-1);}private void check(boolean ok,String s){if(!ok)throw new AssertionError(s);report.append("PASS ").append(s).append('\n');}private void send(String s){main(()->{try{((EditText)field("input")).setText(s);((Button)field("send")).performClick();}catch(Exception e){throw new RuntimeException(e);}});}private void waitDone()throws Exception {long due=SystemClock.uptimeMillis()+240000;while(SystemClock.uptimeMillis()<due){AtomicBoolean done=new AtomicBoolean();main(()->{try{done.set(!(Boolean)field("busy"));}catch(Exception e){throw new RuntimeException(e);}});if(done.get())return;SystemClock.sleep(200);}throw new AssertionError("Real request exceeded 240 seconds");}
 public void onStart(){Bundle result=new Bundle();LocalStore store=new LocalStore(getTargetContext());try{File keyFile=new File(getTargetContext().getFilesDir(),"test-key.txt");String key;try(InputStream in=new FileInputStream(keyFile);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] bytes=new byte[4096];int n;while((n=in.read(bytes))!=-1)out.write(bytes,0,n);key=out.toString("UTF-8").trim();}keyFile.delete();store.key(key);key=null;store.save(new JSONObject().put("chats",new JSONArray()).put("streaming",true).put("effort","low").toString());activity=(NativeActivity)startActivitySync(new Intent(getTargetContext(),NativeActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();send("请用web_search核实DeepSeek官方Search与Fetch API的用途，生成一份300字以内的Word文档，附真实来源URL。不要只提供下载链接，请实际调用create_file。");waitDone();JSONObject answer=last();check(answer.optString("status").equals("complete"),"real streaming agent turn completes");check(answer.optJSONArray("sources")!=null&&answer.getJSONArray("sources").length()>0,"official live search returns actual public sources");check(answer.optLong("searchedAt")>0,"real search records retrieval time");JSONArray files=answer.optJSONArray("artifacts");check(files!=null&&files.length()>0,"real model invokes local file generation");JSONObject artifact=files.getJSONObject(0);try(ZipFile zip=new ZipFile(ArtifactFiles.resolve(activity,artifact.getString("id")))){check(zip.getEntry("word/document.xml")!=null,"real generated Word is a valid document archive");}JSONArray protocol=answer.getJSONArray("protocol");boolean search=false,file=false,thought=false;for(int i=0;i<protocol.length();i++){JSONObject item=protocol.getJSONObject(i);JSONArray calls=item.optJSONArray("tool_calls");for(int j=0;calls!=null&&j<calls.length();j++){String name=calls.getJSONObject(j).getJSONObject("function").optString("name");search|=name.equals("web_search");file|=name.equals("create_file");}thought|=!item.optString("reasoning_content").isEmpty();}check(search&&file&&thought,"real thinking-mode tool transcript survives multiple requests");
 main(()->{try{JSONObject state=(JSONObject)field("state");state.put("streaming",false);state.put("effort","off");}catch(Exception e){throw new RuntimeException(e);}});send("无需检索。请调用create_file生成一份PDF：标题为二阶系统，正文说明闭环传递函数，展示公式 \\[G(s)=\\frac{100}{s^2+14s+100}\\]，并列一张参数表。要创建PDF文件，不要仅输出正文。");waitDone();JSONObject pdf=last();check(pdf.optString("status").equals("complete"),"real non-streaming agent turn completes");JSONArray pdfs=pdf.optJSONArray("artifacts");check(pdfs!=null&&pdfs.length()>0&&pdfs.getJSONObject(0).optString("format").equals("pdf"),"real model creates requested PDF");check(ArtifactFiles.resolve(activity,pdfs.getJSONObject(0).getString("id")).length()>1000,"real native PDF has substantive content");Bundle ids=new Bundle();ids.putString("real_pdf",pdfs.getJSONObject(0).getString("id"));ids.putString("real_docx",artifact.getString("id"));sendStatus(1,ids);result.putString("report",report.toString());finish(Activity.RESULT_OK,result);
 }catch(Throwable e){result.putString("report",report+"FAIL "+e);finish(Activity.RESULT_CANCELED,result);}finally{try{store.key("");new File(getTargetContext().getFilesDir(),"test-key.txt").delete();}catch(Exception ignored){}}}
}
